/// `Enum(text)` by the enum's name: the value it names, or `None` where the tag raises `ValueError`.
/// The outer `None` is an enum this vocabulary does not have.
pub fn parse_member(enum_name: &str, text: &str) -> Option<Option<&'static str>> {
    Some(match enum_name {
        "CapabilityKind" => CapabilityKind::parse(text).map(CapabilityKind::as_str),
        "ArmingState" => ArmingState::parse(text).map(ArmingState::as_str),
        "Actor" => Actor::parse(text).map(Actor::as_str),
        "OffReason" => OffReason::parse(text).map(OffReason::as_str),
        "ArmingWarning" => ArmingWarning::parse(text).map(ArmingWarning::as_str),
        "Refusal" => Refusal::parse(text).map(Refusal::as_str),
        "JournalCode" => JournalCode::parse(text).map(JournalCode::as_str),
        "RecordState" => RecordState::parse(text).map(RecordState::as_str),
        "OverrideKind" => OverrideKind::parse(text).map(OverrideKind::as_str),
        "OptionKey" => OptionKey::parse(text).map(OptionKey::as_str),
        "WordingKey" => WordingKey::parse(text).map(WordingKey::as_str),
        "KeepOn" => KeepOn::parse(text).map(KeepOn::as_str),
        "Ceiling" => Ceiling::parse(text).map(Ceiling::as_str),
        "Field" => Field::parse(text).map(Field::as_str),
        "BridgeCommand" => BridgeCommand::parse(text).map(BridgeCommand::as_str),
        "Measurement" => Measurement::parse(text).map(Measurement::as_str),
        "ObservedWord" => ObservedWord::parse(text).map(ObservedWord::as_str),
        "RunEnd" => RunEnd::parse(text).map(RunEnd::as_str),
        "ChatState" => ChatState::parse(text).map(ChatState::as_str),
        "ChatReason" => ChatReason::parse(text).map(ChatReason::as_str),
        "RuleState" => RuleState::parse(text).map(RuleState::as_str),
        "RuleReason" => RuleReason::parse(text).map(RuleReason::as_str),
        "SpendOutcome" => SpendOutcome::parse(text).map(SpendOutcome::as_str),
        "GoalStatus" => GoalStatus::parse(text).map(GoalStatus::as_str),
        "AutoResult" => AutoResult::parse(text).map(AutoResult::as_str),
        "CheckReach" => CheckReach::parse(text).map(CheckReach::as_str),
        "CheckGrade" => CheckGrade::parse(text).map(CheckGrade::as_str),
        "Verdict" => Verdict::parse(text).map(Verdict::as_str),
        "NoteCode" => NoteCode::parse(text).map(NoteCode::as_str),
        "ReportRefusal" => ReportRefusal::parse(text).map(ReportRefusal::as_str),
        "ReportStatus" => ReportStatus::parse(text).map(ReportStatus::as_str),
        "ReportWrite" => ReportWrite::parse(text).map(ReportWrite::as_str),
        "WebReason" => WebReason::parse(text).map(WebReason::as_str),
        "McpTool" => McpTool::parse(text).map(McpTool::as_str),
        "ContinuationKind" => ContinuationKind::parse(text).map(ContinuationKind::as_str),
        "ContinuationReason" => ContinuationReason::parse(text).map(ContinuationReason::as_str),
        "KeepState" => KeepState::parse(text).map(KeepState::as_str),
        "KeepReason" => KeepReason::parse(text).map(KeepReason::as_str),
        "PromptTrigger" => PromptTrigger::parse(text).map(PromptTrigger::as_str),
        "PromptEvery" => PromptEvery::parse(text).map(PromptEvery::as_str),
        "PromptState" => PromptState::parse(text).map(PromptState::as_str),
        "PromptReason" => PromptReason::parse(text).map(PromptReason::as_str),
        "WhileRunning" => WhileRunning::parse(text).map(WhileRunning::as_str),
        "CourierChannel" => CourierChannel::parse(text).map(CourierChannel::as_str),
        "CourierEvent" => CourierEvent::parse(text).map(CourierEvent::as_str),
        "OutboxState" => OutboxState::parse(text).map(OutboxState::as_str),
        "FeedWord" => FeedWord::parse(text).map(FeedWord::as_str),
        "OpenOutcome" => OpenOutcome::parse(text).map(OpenOutcome::as_str),
        "HookOutcome" => HookOutcome::parse(text).map(HookOutcome::as_str),
        "PlanWord" => PlanWord::parse(text).map(PlanWord::as_str),
        "SteerState" => SteerState::parse(text).map(SteerState::as_str),
        "SteerReason" => SteerReason::parse(text).map(SteerReason::as_str),
        _ => return None,
    })
}

/// The off reasons that are tripwires, in the enum's order (a set in Python).
pub const TRIPWIRES: &[OffReason] = &[OffReason::SubmissionUnknown, OffReason::LocalCheckFailed, OffReason::FailedHere, OffReason::Incompatible, OffReason::HookException, OffReason::StatementChanged, OffReason::MeasurementFailed, OffReason::AutoCheckFailed, OffReason::DuplicateSeen, OffReason::NotDeliveredOnOpen, OffReason::RequirementOff, OffReason::NotDispatchedBySession, OffReason::RefusedByCodex, OffReason::BadCodes];
/// What a kept-on capability notes, most serious first: the order matters.
pub const KEPT_NOTICES: &[OffReason] = &[OffReason::DuplicateSeen, OffReason::StatementChanged, OffReason::FailedHere, OffReason::LocalCheckFailed, OffReason::Incompatible, OffReason::MeasurementFailed, OffReason::AutoCheckFailed, OffReason::NotDeliveredOnOpen, OffReason::NotDispatchedBySession, OffReason::RefusedByCodex, OffReason::RequirementOff, OffReason::EngineChanged, OffReason::SubmissionUnknown, OffReason::HookException];
pub const NOTE_FOR_PASS: &[NoteCode] = &[NoteCode::AsExpected];
pub const NOTE_FOR_FAIL: &[NoteCode] = &[NoteCode::NotAsExpected, NoteCode::Partial, NoteCode::PreconditionUnmet, NoteCode::Inconclusive];
